using UnityEngine;

namespace Astrea.BattleActions;

[CreateAssetMenu(fileName = "BlazingChantingAction", menuName = "Data/Battle/Battle Actions/Sothis/BlazingChanting Action")]
public class BlazingChantingAction : ChantingAction
{
	[Header("Blazing Chanting Action")]
	[SerializeField]
	private AfflictionDefaultEffectAction afflictionSameTargetAction;

	[SerializeField]
	private DrawAction drawAction;

	[SerializeField]
	private int drawDiceAmount = 1;

	public AfflictionDefaultEffectAction AfflictionSameTargetAction => afflictionSameTargetAction;

	public DrawAction DrawAction => drawAction;

	public int DrawDiceAmount => drawDiceAmount;

	public override void CastTargetAmount(GameObject target, int amount, GameObject source)
	{
		drawAction.CastAmount(drawDiceAmount, source);
		CastTarget(target, source);
		afflictionSameTargetAction.CastTargetAmount(target, amount, source);
	}
}
